from lib import *
S = SS('t6')
steps = [
    step("一次 TCC 事务的三个动作各改了什么。账户和库存是两个独立的 MySQL 实例上的两个服务。成功路径:账户 Try 把 80 从 balance 挪到 frozen、库存 Try 把 1 件从 avail 挪到 locked,Confirm 再把它们挪到 spent 和 sold,结果账户 (balance, frozen, spent) = (920, 0, 80)、库存 (avail, locked, sold) = (9, 0, 1)。取消路径:Try 之后 Cancel,把冻结的和预留的挪回去,状态回到这单之前的 (920, 0, 80)、(9, 0, 1)。Try 失败路径:余额只有 50 买不起 80 的商品,账户 Try 失败,没有已经 Try 的服务要 Cancel,状态不变。每个动作都是本服务自己的一次本地提交。", t=tl(S(1)), mark=lidx(S(1), 'Try 失败:账户 1 余额不足'), done=lidx(S(1), '→ CONFIRMED', '→ CANCELLED', '→ REJECTED'), kv=KV([['Try', '检查并把资源挪到“冻结 / 预留”列'], ['Confirm', '把冻结的挪到“已用 / 已售”列'], ['Cancel', '把冻结的挪回“可用”列']], ['Try'])),
    step("Try 到 Confirm 之间,资源是被业务层“预留”的,而不是被数据库锁住。订单 A 在 Try 之后停 hold 毫秒再 Confirm,订单 B 同时去买同一个商品、扣同一个账户。hold=0 时 B(TCC)耗时 0.6 ms、B(XA)耗时 0.7 ms(50 次中位数)。hold=200 ms:B(TCC)1.3 ms,B(XA)179.5 ms。hold=500 ms:B(TCC)2.5 ms,B(XA)423.3 ms。TCC 里 A 的 Try 在各自的本地事务里已经提交,行锁早就放了,B 不用等;XA 里 A 的行锁从 PREPARE 一直握到 COMMIT,B 要等到 A 提交。这是 TCC 最大的卖点:不长时间持有数据库锁。", t=tl(S(2)), mark=lidx(S(2), '500 ms'), done=lidx(S(2), '0 ms', '200 ms'), b=bars([['hold=200 B(TCC) ms', 1.3, '1.3'], ['hold=200 B(XA) ms', 179.5, '179.5'], ['hold=500 B(TCC) ms', 2.5, '2.5'], ['hold=500 B(XA) ms', 423.3, '423.3']], 430, done=[0, 2], mark=[1, 3]), kv=KV([['TCC', 'Try 已提交,行锁已释放,B 不用等'], ['XA', '行锁握到 COMMIT,B 等 A'], ['代价', '资源在业务层被预留']], ['TCC'])),
    step("Try 必须在一条语句里同时“检查并预留”。库存 100、150 个订单用 16 个线程并发抢。把条件写进 UPDATE 的 WHERE(avail >= n):成功 100、被拒 50,最终 avail=0、locked=100、sold=0,avail + locked + sold = 100,没有超卖。对照“先 SELECT 看够不够、再 UPDATE 扣”这种检查和扣减分成两条语句的写法:成功 115、被拒 35,最终 avail=-15、locked=115,多卖了 15 件(为了能看到负数,实验里先把 CHECK 约束拿掉了)。检查和修改不在同一条语句里,并发就会穿过检查。", t=tl(S(3)), mark=lidx(S(3), '先 SELECT 再 UPDATE'), done=lidx(S(3), '条件 UPDATE'), b=bars([['条件 UPDATE:成功', 100, '100'], ['先 SELECT 再 UPDATE:成功', 115, '115(超卖 15)']], 120, done=[0], mark=[1]), kv=KV([['条件 UPDATE', '成功 100,没有超卖'], ['先查再改', '成功 115,多卖 15 件'], ['原因', '检查与扣减之间有并发空隙']], ['原因'])),
    step("并发压力下检查不变量。4 个线程共 2000 个订单,结局随机(60% Confirm、30% Cancel、10% 管理器在 Try 之后崩溃),另一个线程每 5 ms 采样一次(账户、库存各一条 SELECT),检查 balance + frozen + spent 和 avail + locked + sold 是否始终等于初始值。结局:Confirm 1175、Cancel 630、崩溃留下 195、被拒 0;采样 222 次,违反不变量 0 次。最终账户 balance=9890400、frozen=15600、spent=94000,其中 frozen = 195 笔崩溃订单 × 80 = 15600;库存 avail=3630、locked=195、sold=1175。总量守恒,但崩溃订单留下的预留没有人处理。", t=tl(S(4)), mark=lidx(S(4), '违反不变量 0 次'), done=lidx(S(4), '最终:账户'), b=bars([['Confirm 订单', 1175, '1175'], ['Cancel 订单', 630, '630'], ['崩溃留下的预留', 195, '195']], 1200, cur=[0, 1], mark=[2]), kv=KV([['采样', '222 次,违反 0 次'], ['总量', 'balance+frozen+spent 守恒'], ['遗留', '195 笔崩溃订单的预留还占着']], ['遗留'])),
    step("管理器崩溃留下的预留会一直占着库存。库存 100、130 个订单,15% 在 Try 之后崩溃,其余 Confirm:卖出 80 件、被崩溃订单占着 20 件、被拒 30 个。这 30 个订单因“库存不足”被拒,但库里其实只卖出了 80 件。朴素版本里 stock 表只有一个总数 locked,没有“这 20 件是哪个订单的”,想释放只能整体清零。试一下整体清零:表上有 CHECK(locked >= 0) 时,订单 X 的 Confirm 随后到达报 3819;没有这个 CHECK 时 Confirm 执行成功,库存变成 (avail=10, locked=-1, sold=1)——已经卖出 1 件、avail 还是 10,总数多了 1。要安全释放,必须有 xid 级别的记录(下一篇)。", t=tl(S(5)), mark=lidx(S(5), '30 个订单因', '(b) 表上没有这个 CHECK'), done=lidx(S(5), '(a) 表上有 CHECK', '3819'), b=bars([['卖出', 80, '80'], ['被崩溃订单占着', 20, '20'], ['因库存不足被拒', 30, '30']], 100, done=[0], mark=[1, 2]), kv=KV([['崩溃订单', '预留永久占着库存'], ['整体清零', '会连在途订单的预留一起释放'], ['出路', '要有 xid 级别的记录']], ['出路'])),
    step("代价(三种写法各 300 次)。单个实例里的本地事务:中位数 0.2 ms、p99 0.5 ms。TCC(两个服务,Try 两次 + Confirm 两次共 4 次服务调用、4 次提交):中位数 0.6 ms(2.9 倍)、p99 1.1 ms。XA(两个实例,2 次 PREPARE + 2 次 COMMIT):中位数 0.7 ms(3.5 倍)、p99 3.8 ms。TCC 每个动作都是普通的单语句提交,没有协调者决定日志和 prepare 状态,尾延迟比 XA 低;代价是业务要给每个服务写 Try、Confirm、Cancel 三套逻辑,并自己负责防重复、防悬挂。", t=tl(S(6)), mark=lidx(S(6), 'XA(两个实例)'), done=lidx(S(6), '本地事务(一个实例)', 'TCC(两个服务)'), b=bars([['本地事务 p99 ms', 0.5, '0.5'], ['TCC p99 ms', 1.1, '1.1'], ['XA p99 ms', 3.8, '3.8']], 4, cur=[0], done=[1], mark=[2]), kv=KV([['中位数', '0.2 → 0.6(TCC)→ 0.7(XA)ms'], ['p99', '0.5 → 1.1 → 3.8 ms'], ['额外成本', '每个服务三套业务逻辑']], ['额外成本'])),
]
A = mkartt('t6', 6, '分布式事务,TCC,Try Confirm Cancel,MySQL,真实验证,动画演示',
    '用两个 MySQL 实例上的账户和库存服务实测 TCC:Try 把资源预留到冻结列、Confirm 转成已用、Cancel 退回;订单 A 在中间停 500 ms,同一行的订单 B 在 TCC 下 2.5 ms、在 XA 下 423.3 ms;检查和预留写成两条语句会多卖 15 件;崩溃订单留下的预留要靠 xid 记录才能安全释放。',
    'TCC 把一个分布式事务拆成 Try、Confirm、Cancel 三个业务动作,每个动作在本服务内各自提交。这样的好处是什么、Try 该怎么写才不会超卖、总量守不守恒、管理器崩溃会留下什么?这篇用真实的 MySQL 把设计要点逐个量出来。',
    [('423.3 ms vs 2.5 ms', '订单 A 在中间停 500 ms 时,同一行上订单 B 的耗时:XA 对 TCC'), ('+15 件', '检查和扣减写成两条语句时,库存 100 被 16 个线程抢出的超卖量'), ('195', '2000 个随机结局的订单里,管理器在 Try 之后崩溃、留下预留的订单数(采样 222 次,守恒检查 0 次违反)')],
    [('三个动作各改什么', '<p>Try 把资源从可用挪到冻结(余额、库存),Confirm 把冻结的挪到已用或已售,Cancel 把冻结的退回可用。每个动作是本服务的一次本地提交,不跨实例。</p>'),
     ('业务层预留代替数据库锁', '<p>Try 提交之后行锁就释放了,别的订单可以继续处理同一行;XA 里行锁从 PREPARE 握到 COMMIT。预留的资源被记在业务列里。</p>'),
     ('Try 要一条语句检查并预留', '<p>条件写进 UPDATE 的 WHERE,检查和修改是同一条语句。先 SELECT 再 UPDATE 在并发下会超卖。</p>'),
     ('总量守恒', '<p>只要每个动作都是原子的单语句,balance + frozen + spent 和 avail + locked + sold 始终等于初始值,并发采样没有违反。</p>'),
     ('崩溃留下的预留', '<p>管理器在 Try 之后崩溃,预留一直占着库存,别人买不到;没有 xid 级别的记录就不知道该释放谁,整体清零会连在途订单的预留一起释放。</p>'),
     ('代价', '<p>TCC 的每个动作都是普通提交,尾延迟比 XA 低;但每个服务要写三套业务逻辑,防重复、防悬挂都靠业务自己。</p>')],
    steps,
    [ENV_T + '。本篇用两个独立的 MySQL 26.7.0 实例(账户服务、库存服务)和一个单实例对照;TCC 是我自己写的 Python 实现(tools/articles/tcc.py),故意不带 xid 记录和防重复保护;XA 对照用的是 MySQL 自带的 XA 语句;“管理器崩溃”是在代码里直接不再发后续调用,不是 kill 进程',
     '没有验证:Seata TCC / Hmily 等框架的实际行为;服务之间的调用是网络请求时的超时、重试与乱序(只用了进程内的函数调用,这些是下一篇的内容);多商品、多账户订单的死锁风险;Confirm / Cancel 失败后的重试策略;CHECK 约束在其它数据库里的行为'],
    'TCC')
